/* The fold lives beside the original rows, so markers, scroll anchors and panel actions still have those rows. */
function workspaceStepFoldChecks(source){
  const log={children:[],querySelectorAll(){return this.children.filter(el=>el.dataset.workspaceStepFold)}};
  const doc={activeElement:null};
  function element(){
    const classes=new Set(),attrs=new Map();
    return {
      dataset:{},children:[],hidden:false,textContent:'',
      classList:{
        add:name=>classes.add(name),contains:name=>classes.has(name),
        toggle(name,force){if(force)classes.add(name);else classes.delete(name)},
        remove(...names){names.forEach(name=>classes.delete(name))},
      },
      set innerHTML(_){
        this.children=Array.from({length:4},element);
        this.children[1].children=Array.from({length:3},element);
      },
      setAttribute:(name,value)=>attrs.set(name,value),
      getAttribute:name=>attrs.get(name)??null,
      removeAttribute:name=>attrs.delete(name),
      focus(){doc.activeElement=this},
      contains(node){return node===this||this.children.includes(node)},
      get nextElementSibling(){const i=log.children.indexOf(this);return i<0?null:log.children[i+1]??null},
      before(node){node.remove();log.children.splice(log.children.indexOf(this),0,node)},
      remove(){const i=log.children.indexOf(this);if(i>=0)log.children.splice(i,1)},
    };
  }
  doc.createElement=element;
  const a={id:'a'},input=element();
  const ctx={WORKSPACE:true,STEADY:false,focus:a.id,OFUI:{docked:true,recipient:'agent'},A:{a},ofLog:log,ofIn:input,document:doc,txt:(el,v)=>el.textContent=v};
  const {workspaceStepFoldsPaint:paint,workspaceStepSummary:summary,workspaceStepRunning:running}=vm.runInNewContext(source+';({workspaceStepFoldsPaint,workspaceStepSummary,workspaceStepRunning})',ctx);
  const kinds=['write','patch','read','edit','web','run','search','search','spawn','spawn','ask','ask','constructor','custom','run','web'];
  const totals=summary(kinds.map((kind,i)=>({kind,err:i===5})));
  assert.equal(totals.count,'16 steps');
  assert.equal(totals.kinds,'2 files, 2 edits, 2 web, 2 commands, 2 searches, 2 hand-offs, 2 questions, 2 other');
  assert.equal(totals.failed,1);
  assert.equal(summary([{kind:'web'}]).kinds,'1 web');
  for(const flag of ['done','err','unknown','stale','over'])assert.equal(running({[flag]:true}),false);
  assert.equal(running({}),true);
  const step=(kind,flags={})=>({kind:'step',eventRef:{kind,...flags},agent:a,el:element()});
  const one=step('run',{err:true}),two=step('read');
  const divider=element();divider.dataset.workspaceNewMarker='true';
  const three=step('web',{done:true}),say={kind:'source',el:element()};
  const hiddenWatch={kind:'watch',el:element()};
  hiddenWatch.el.hidden=true;
  const rows=[one,hiddenWatch,two,three,say];
  log.children=[one.el,hiddenWatch.el,two.el,divider,three.el,say.el];
  const folded=row=>row.el.classList.contains('workspace-step-fold-hidden');
  paint(rows);
  const [first,second]=log.querySelectorAll();
  assert.deepEqual(log.children,[first,one.el,hiddenWatch.el,two.el,divider,second,three.el,say.el]);
  assert.equal(first.getAttribute('aria-expanded'),'false');
  assert.equal(first.children[1].children[0].textContent,'1 step');
  assert.equal(first.children[2].textContent,'1 failed');
  assert.equal(folded(one),true);
  assert.equal(folded(two),false,'pending step remains visible');
  assert.equal(two.el.classList.contains('workspace-step-tight'),true,'a hidden Motet row cannot break the visible run spacing');
  first.focus();first.onclick();
  assert.equal(doc.activeElement,first);
  assert.equal(folded(one),false);
  two.eventRef.done=true;
  paint(rows);
  assert.equal(log.querySelectorAll()[0],first);
  assert.equal(first.getAttribute('aria-expanded'),'true');
  assert.equal(first.children[1].children[0].textContent,'2 steps');
  assert.equal(first.children[1].children[2].textContent,'1 command, 1 file');
  assert.equal(folded(two),false,'completed step joins the same open fold');
  ctx.OFUI.recipient='watch';paint(rows);
  assert.equal(first.hidden,true,'the alternate recipient does not show a step summary');
  ctx.OFUI.recipient='agent';paint(rows);
  assert.equal(log.querySelectorAll()[0],first);
  assert.equal(first.hidden,false);
  assert.equal(first.getAttribute('aria-expanded'),'true','the same desk retains its expanded fold');
  two.el.classList.add('workspace-new-dot');
  paint(rows);
  first.onclick();
  assert.equal(folded(two),true);
  assert.equal(first.dataset.new,'true','collapsed fold still indicates new activity');
  assert.equal(folded(three),true,'divider prevents an unrelated run opening');
  const four=step('patch');
  divider.before(four.el);rows.splice(3,0,four);
  four.el.focus();four.eventRef.done=true;
  paint(rows);
  assert.equal(doc.activeElement,first,'focused running step that folds moves focus to its disclosure');
  ctx.focus=null;paint(rows);
  assert.equal(log.querySelectorAll().length,0);
  ctx.focus=a.id;paint(rows);
  assert.notEqual(log.querySelectorAll()[0],first);
  assert.equal(log.querySelectorAll()[0].getAttribute('aria-expanded'),'false');
}
